# 该工具由于处理 findsomething 或小程序敏感信息获取到的 Js 接口
# Input 的最后一行可以手动添加想要包含的字符串或不想要包含的字符串（格式如下,最好不要有多余的空格）
# rule:test.com,test2.com 或 rule:!test3.com,!test4.com

handle = func(origin /*string*/) {
    domain = ""
    # '/pages/' 需自行判断是接口路径，还是小程序页面
    exclude = ['.js','.wxml','.wxss','.mp3','.mp4','.jpg','.png','/components/','.ttf','.vue',".woff","mjs",".scss",".less",".tnpmrc",".tnpm",".jst",".jhtml",".wasm",".wasm",".svg", ".swf",".wxs",".dtd",".fdf",".vue",".eot",".left","text/css","text/html","text/javascript","application/json","text/plain"]
    origin = origin.ReplaceAll("\r", "")
    origins = str.RemoveRepeat(str.Split(origin, "\n"))
    # 去除最后一行的换行
    if origins[-1] == "\n"{
        origins.Pop()
    }
    self_include = [""]
    self_exclude = []
    rules = []
    result = []    # 存放最后的结果
    flag = true    # 判断是否 self_include 是否为空

    if origins[-1].StartsWith("rule:"){
        text = str.Replace(origins[-1],"rule:","",1)
        rules = str.SplitAndTrim(text /*type: string*/, "," /*type: string*/)
        for rule in rules{
            if rule.StartsWith("!"){
                self_exclude.Append(str.Replace(rule,"!","",1))
                continue
            }
            self_include.Append(rule)
            flag = false
        }
        origins.Pop()
    }

    if self_include.Length()>1 {
        self_include.Shift()
    }

    # 对 self_exclude、exclude 数组进行合并
    self_exclude = str.RemoveRepeat(self_exclude + exclude /*type: []string*/) 


    # 进行分类
    if flag {
        for dir in origins{
            if dir == "\n" {
                continue
            }
            if !str.StringContainsAnyOfSubString(dir /*type: string*/, self_exclude /*type: []string*/){
                result.Append(dir)
            }
        }
    } else {
        for dir in origins{
            if dir == "\n" {
                continue
            }
            if str.StringContainsAnyOfSubString(dir /*type: string*/, self_include /*type: []string*/) {
                result.Append(dir)
            }
        }
    }

    # 返回处理后的数据
    return str.Join(result,"\n")
}
